 if($path==='/about'){layout('Our story',function(){echo '<section class="section about-page"><div class="center-heading"><p class="eyebrow">OUR STORY</p><h1>Goodness, made part of every day.</h1></div><div class="category-editorial"><p>White Gold Farm brings familiar dairy favourites to your table: milk for the morning chai, makhan for a warm paratha, desi ghee for treasured recipes and paneer for family meals.</p><h2>Our promise</h2><p>We care about purity, careful handling and honest service. Speak to our team for product details, larger orders or delivery questions.</p><a class="button" href="/products">Explore our collection →</a></div></section>';});exit;}
 if($path==='/contact'){layout('Contact us',function(){echo '<section class="section"><div class="center-heading"><p class="eyebrow">LET’S TALK</p><h1>Your favourites are a call away.</h1></div><div class="contact-cards"><article><h2>Call our team</h2><p><a href="tel:03015813887">0301 5813887</a><br><a href="tel:03414428939">0341 4428939</a></p></article><article><h2>Order on WhatsApp</h2><a class="button" href="https://wa.me/923414428939?text=Hello%20White%20Gold%20Farm">Start a conversation ↗</a></article></div></section>';});exit;}
 if($path==='/checkout/success'){layout('Order received',function(){ $ref=$_SESSION['confirmation']??null;echo '<section class="confirmation"><div class="success-check">✓</div><p class="eyebrow">THANK YOU FOR CHOOSING WHITE GOLD</p><h1>'.($ref?'Thank you for your order.':'Let’s bring goodness home.').'</h1>';if($ref)echo '<p>Our team will call to confirm delivery. Keep your order reference below.</p><div class="order-id">Order reference<br>'.e($ref).'</div>';echo '<p>Cash on delivery · Questions? <a href="tel:03414428939">0341 4428939</a></p><a class="button" href="/products">Continue shopping →</a></section>';},true);exit;}
 if($path==='/checkout'){layout('Checkout',function(){global $config;?><section class="section page-section"><div class="center-heading"><p class="eyebrow">GOODNESS IS ON ITS WAY</p><h1>Make it yours.</h1></div><div class="checkout-grid"><form id="checkout" class="form-panel"><h2>Delivery details</h2><p>We’ll call to confirm your order.</p><div class="form-grid"><?php field('full_name','Full name');field('phone','Mobile number','','tel');?></div><label class="field">Delivery address<textarea name="address" minlength="10" maxlength="500" required autocomplete="street-address"></textarea></label><?php field('city','City');?><div class="delivery-card"><h3 id="delivery-heading">Check your delivery area</h3><p id="delivery-copy"></p><div id="location-fields"><button type="button" id="locate" class="button outline">Use my current location</button><details id="coordinates"><summary>Choose or change delivery coordinates</summary><div class="form-grid"><label class="field">Latitude<input id="latitude" type="number" step="any" min="-90" max="90"></label><label class="field">Longitude<input id="longitude" type="number" step="any" min="-180" max="180"></label></div></details><div id="location-map" data-maps-key="<?=e($config['maps_key'])?>"></div><p id="location-status" role="status"></p><small>Choose the delivery address location. Your pin is saved with the order.</small></div></div><label class="field">Order notes (optional)<textarea name="notes" maxlength="1000"></textarea></label><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><div class="payment-box"><strong>Cash on delivery</strong><p>Pay when your order arrives. No card details needed.</p></div><p class="error-text" id="checkout-error" role="alert"></p><button id="place-order" class="button full">Place order →</button></form><aside class="summary-panel"><h2>Your order</h2><div id="checkout-items"></div><div class="summary-total row between"><span>Total</span><strong id="checkout-total"></strong></div><p>No delivery fee is added at checkout. Availability will be confirmed by phone.</p><a href="/products" class="text-link">← Add more products</a></aside></div></section><?php },true);exit;}
 http_response_code(404);layout('Page not found',fn()=>print('<section class="empty"><h1>That page isn’t here.</h1><a href="/products" class="button">Explore products</a></section>'),true);
